// State Variables
let currentArticle = BLOG_POSTS_DATABASE[0];
let currentPhotoIndex = 0;
let homepageFilterCategory = "All Blogs";
let homepageSearchQuery = "";
let homepageCurrentPage = 1;
let categoryCurrentPage = 1;
const ITEMS_PER_PAGE = 12;

function renderPaginationControls(container, currentPage, totalPages, totalItems, onPageChange) {
  if (!container) return;
  if (totalPages <= 1) {
    container.innerHTML = "";
    return;
  }

  let pages = [];
  if (totalPages <= 7) {
    for (let i = 1; i <= totalPages; i++) pages.push(i);
  } else {
    pages.push(1);
    if (currentPage > 3) pages.push('...');
    
    let start = Math.max(2, currentPage - 1);
    let end = Math.min(totalPages - 1, currentPage + 1);
    
    if (currentPage <= 3) {
      start = 2;
      end = 4;
    } else if (currentPage >= totalPages - 2) {
      start = totalPages - 3;
      end = totalPages - 1;
    }

    for (let i = start; i <= end; i++) pages.push(i);

    if (currentPage < totalPages - 2) pages.push('...');
    pages.push(totalPages);
  }

  const buttonsHTML = pages.map(p => {
    if (p === '...') {
      return `<span class="page-ellipsis">...</span>`;
    }
    return `<button class="page-btn ${p === currentPage ? 'active' : ''}" data-page="${p}">${p}</button>`;
  }).join("");

  const prevBtn = `<button class="page-btn" data-page="${currentPage - 1}" ${currentPage === 1 ? 'disabled' : ''}><i class="fas fa-chevron-left"></i> Prev</button>`;
  const nextBtn = `<button class="page-btn" data-page="${currentPage + 1}" ${currentPage === totalPages ? 'disabled' : ''}>Next <i class="fas fa-chevron-right"></i></button>`;

  container.innerHTML = `
    <div class="pagination-wrapper">
      <div class="pagination-controls">
        ${prevBtn}
        ${buttonsHTML}
        ${nextBtn}
      </div>
      <div class="pagination-info">Page ${currentPage} of ${totalPages}</div>
    </div>
  `;

  container.querySelectorAll(".page-btn[data-page]").forEach(btn => {
    btn.addEventListener("click", () => {
      const targetPage = parseInt(btn.getAttribute("data-page"), 10);
      if (targetPage >= 1 && targetPage <= totalPages && targetPage !== currentPage) {
        onPageChange(targetPage);
      }
    });
  });
}

document.addEventListener("DOMContentLoaded", () => {
  const isArticlePage = document.getElementById("articleHeroTitle") !== null;
  const isCategoryPage = document.getElementById("categoryHeading") !== null;

  if (isArticlePage) {
    initArticlePage();
  } else if (isCategoryPage) {
    initCategoryPage();
  } else {
    initHomepage();
  }

  initMobileMenu();
  initGlobalSearch();
  initCopyProtection();
});

/* ==========================================================================
   CATEGORY PAGE ARCHIVE LOGIC
   ========================================================================== */
function initCategoryPage() {
  categoryCurrentPage = 1;
  const urlParams = new URLSearchParams(window.location.search);
  const catNameParam = document.body.getAttribute('data-category') || urlParams.get('cat') || 'Haircuts';

  const categoryDescriptions = {
    "Haircuts": "Discover salon-tested haircut guides, choppy layers, bobs, and fringe styles curated by licensed stylists.",
    "Hairstyles": "Explore signature hairstyle ideas, wave techniques, sleek updos, and effortless styling for every occasion.",
    "Hair Color": "Browse hand-painted balayage guides, silver highlights, honey blondes, and low-maintenance tone trends.",
    "Guides": "Comprehensive stylist guides covering hair density, face shape matching, damage repair, and salon care."
  };

  const categoryIcons = {
    "Haircuts": "fa-cut",
    "Hairstyles": "fa-spa",
    "Hair Color": "fa-palette",
    "Guides": "fa-book-open"
  };

  const titleEl = document.getElementById("categoryPageTitle");
  const kickerEl = document.getElementById("categoryKicker");
  const headingEl = document.getElementById("categoryHeading");
  const descEl = document.getElementById("categoryDescription");
  const breadcrumbEl = document.getElementById("breadcrumbCatName");
  const sectionTitleEl = document.getElementById("categorySectionTitle");
  const badgeEl = document.getElementById("articleCountBadge");
  const gridEl = document.getElementById("categoryPostsGrid");
  const searchInput = document.getElementById("categorySearchInput");

  const normalizedCat = catNameParam.trim();
  const iconClass = categoryIcons[normalizedCat] || 'fa-folder-open';

  // Highlight active pill button
  document.querySelectorAll(".cat-pill-btn[data-cat]").forEach(pill => {
    if (pill.getAttribute("data-cat").toLowerCase() === normalizedCat.toLowerCase()) {
      pill.classList.add("active");
    } else {
      pill.classList.remove("active");
    }
  });

  if (titleEl) titleEl.textContent = `${normalizedCat} Category Guide | Women Hairstyles`;
  if (kickerEl) kickerEl.innerHTML = `<i class="fas ${iconClass}"></i> CATEGORY COLLECTION`;
  if (headingEl) headingEl.textContent = normalizedCat;
  if (descEl) descEl.textContent = categoryDescriptions[normalizedCat] || `Explore curated ${normalizedCat} guides and lookbooks.`;
  if (breadcrumbEl) breadcrumbEl.textContent = normalizedCat.toUpperCase();
  if (sectionTitleEl) sectionTitleEl.textContent = `${normalizedCat} Guides & Lookbooks`;

  function renderGrid(query = '') {
    const matchedPosts = BLOG_POSTS_DATABASE.filter(post => {
      const isCatMatch = post.category.toLowerCase() === normalizedCat.toLowerCase() ||
                         post.tag.toLowerCase().includes(normalizedCat.toLowerCase());
      const q = query.toLowerCase().trim();
      const isSearchMatch = !q || post.heroTitle.toLowerCase().includes(q) || post.introText.toLowerCase().includes(q);
      return isCatMatch && isSearchMatch;
    });

    const totalPages = Math.ceil(matchedPosts.length / ITEMS_PER_PAGE) || 1;
    if (categoryCurrentPage > totalPages) categoryCurrentPage = totalPages;
    if (categoryCurrentPage < 1) categoryCurrentPage = 1;

    if (badgeEl) {
      badgeEl.style.display = "none";
    }

    if (gridEl) {
      if (matchedPosts.length === 0) {
        gridEl.innerHTML = `
          <div style="grid-column: 1/-1; text-align: center; padding: 4rem 1rem; color: #777;">
            <h3 class="font-serif" style="font-size: 1.6rem; margin-bottom: 0.5rem;">No articles found in "${normalizedCat}"</h3>
            <p style="color: var(--text-muted);">Try adjusting your search query or view all guides.</p>
          </div>
        `;
        let pagEl = document.getElementById("categoryPagination");
        if (pagEl) pagEl.innerHTML = "";
        return;
      }

      const startIdx = (categoryCurrentPage - 1) * ITEMS_PER_PAGE;
      const pagePosts = matchedPosts.slice(startIdx, startIdx + ITEMS_PER_PAGE);

      gridEl.innerHTML = pagePosts.map(createBlogCardHTML).join("");
    }

    let pagContainer = document.getElementById("categoryPagination");
    if (!pagContainer) {
      pagContainer = document.createElement("div");
      pagContainer.id = "categoryPagination";
      pagContainer.style.gridColumn = "1 / -1";
      gridEl.parentNode.appendChild(pagContainer);
    }

    renderPaginationControls(pagContainer, categoryCurrentPage, totalPages, matchedPosts.length, (newPage) => {
      categoryCurrentPage = newPage;
      renderGrid(searchInput ? searchInput.value : '');
      const gridSection = document.getElementById("categoryPostsGrid");
      if (gridSection) gridSection.scrollIntoView({ behavior: "smooth" });
    });
  }

  renderGrid();

  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      categoryCurrentPage = 1;
      renderGrid(e.target.value);
    });
  }
}

function createBlogCardHTML(post) {
  return `
    <article class="blog-card" onclick="openBlogArticle('${post.id}')">
      <div class="blog-card-media">
        <img src="${post.thumbnail}" alt="${post.heroTitle}" loading="lazy">
      </div>
      <div class="blog-card-body">
        <span class="blog-card-category-pink">${post.tag}</span>
        <h3 class="blog-card-title">${post.heroTitle}</h3>
        <p class="blog-card-excerpt">${post.introText}</p>
        <div class="blog-card-footer-meta">
          <span class="meta-author">By ${post.authorName}</span>
          <span class="meta-readtime">${post.readTime}</span>
        </div>
      </div>
    </article>
  `;
}

function initMobileMenu() {
  const openBtn = document.getElementById("mobileMenuBtn");
  const closeBtn = document.getElementById("mobileNavClose");
  const drawer = document.getElementById("mobileNavOverlay");

  if (openBtn && drawer) {
    openBtn.addEventListener("click", () => drawer.classList.add("active"));
  }
  if (closeBtn && drawer) {
    closeBtn.addEventListener("click", () => drawer.classList.remove("active"));
  }
}

/* ==========================================================================
   HOMEPAGE LOGIC (CLEAN COVER IMAGES WITHOUT PIN BUTTONS)
   ========================================================================== */
function initHomepage() {
  homepageCurrentPage = 1;
  renderHomepageFeed();

  // Search Bar
  const searchInput = document.getElementById("homeSearchInput");
  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      homepageSearchQuery = e.target.value.toLowerCase().trim();
      homepageCurrentPage = 1;
      renderHomepageFeed();
    });
  }

  // Category Pills
  const catBtns = document.querySelectorAll(".cat-pill-btn");
  catBtns.forEach(btn => {
    btn.addEventListener("click", () => {
      catBtns.forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      homepageFilterCategory = btn.getAttribute("data-category");
      homepageCurrentPage = 1;
      renderHomepageFeed();
    });
  });
}

function initHaircutQuiz() {
  const quizBtn = document.getElementById("btnQuizSubmit");
  if (!quizBtn) return;

  quizBtn.addEventListener("click", () => {
    const length = document.getElementById("quizHairLength")?.value || "all";
    const texture = document.getElementById("quizHairTexture")?.value || "all";
    
    if (texture !== "all") {
      homepageSearchQuery = texture.toLowerCase();
    } else if (length !== "all") {
      homepageSearchQuery = length.toLowerCase();
    } else {
      homepageSearchQuery = "";
    }
    homepageCurrentPage = 1;
    renderHomepageFeed();

    const gridSection = document.getElementById("homepagePostsGrid");
    if (gridSection) {
      gridSection.scrollIntoView({ behavior: "smooth" });
    }
  });
}

function renderHomepageFeed() {
  const grid = document.getElementById("homepagePostsGrid");
  if (!grid) return;

  const filtered = BLOG_POSTS_DATABASE.filter(post => {
    const matchesCat = homepageFilterCategory === "All Blogs" || post.category === homepageFilterCategory;
    const matchesSearch = homepageSearchQuery === "" ||
      post.heroTitle.toLowerCase().includes(homepageSearchQuery) ||
      post.introText.toLowerCase().includes(homepageSearchQuery) ||
      post.tag.toLowerCase().includes(homepageSearchQuery);

    return matchesCat && matchesSearch;
  });

  const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE) || 1;
  if (homepageCurrentPage > totalPages) homepageCurrentPage = totalPages;
  if (homepageCurrentPage < 1) homepageCurrentPage = 1;

  if (filtered.length === 0) {
    grid.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; padding: 4rem 1rem;">
        <h3 class="font-serif" style="font-size: 1.6rem; margin-bottom: 0.5rem;">No Haircut Blogs Found</h3>
        <p style="color: var(--text-muted);">Try selecting 'All Blogs' or clearing your search input.</p>
      </div>
    `;
    let pagContainer = document.getElementById("homepagePagination");
    if (pagContainer) pagContainer.innerHTML = "";
    return;
  }

  const startIdx = (homepageCurrentPage - 1) * ITEMS_PER_PAGE;
  const pagePosts = filtered.slice(startIdx, startIdx + ITEMS_PER_PAGE);

  grid.innerHTML = pagePosts.map(createBlogCardHTML).join("");

  let pagContainer = document.getElementById("homepagePagination");
  if (!pagContainer) {
    pagContainer = document.createElement("div");
    pagContainer.id = "homepagePagination";
    pagContainer.style.gridColumn = "1 / -1";
    grid.parentNode.appendChild(pagContainer);
  }

  renderPaginationControls(pagContainer, homepageCurrentPage, totalPages, filtered.length, (newPage) => {
    homepageCurrentPage = newPage;
    renderHomepageFeed();
    const gridSection = document.getElementById("homepagePostsGrid");
    if (gridSection) gridSection.scrollIntoView({ behavior: "smooth" });
  });
}

function openBlogArticle(id) {
  window.location.href = `${id}.html`;
}

/* ==========================================================================
   ARTICLE PAGE LOGIC (STRICT PINTEREST PIN BUTTONS HERE)
   ========================================================================== */
function initArticlePage() {
  const urlParams = new URLSearchParams(window.location.search);
  let articleId = urlParams.get('id');

  if (!articleId) {
    const path = window.location.pathname;
    let filename = path.substring(path.lastIndexOf('/') + 1);
    try {
      filename = decodeURIComponent(filename);
    } catch(e) {}
    articleId = filename.replace('.html', '').replace('.htm', '');
  }

  if (articleId) {
    articleId = articleId.toLowerCase().trim();
  }

  currentArticle = BLOG_POSTS_DATABASE.find(a => a.id.toLowerCase() === articleId);

  if (!currentArticle) {
    // If not found in JS database, preserve pre-rendered static HTML content!
    initTouchSwipe();
    window.addEventListener("scroll", updateReadingProgressBar);
    return;
  }

  currentPhotoIndex = 0;

  renderArticlePage();
  renderRelatedArticlesFeed();
  initTouchSwipe();

  window.addEventListener("scroll", updateReadingProgressBar);
}

function toggleToc() {
  const container = document.getElementById("jumpTocContainer");
  const chevron = document.getElementById("tocChevron");

  if (!container) return;
  const isCollapsed = container.classList.toggle("collapsed");

  if (chevron) {
    chevron.className = isCollapsed ? "fas fa-chevron-down toc-chevron" : "fas fa-chevron-up toc-chevron";
  }
}

function renderArticlePage() {
  if (!currentArticle) return;

  // Render Header Info
  const titleEl = document.getElementById("articleHeroTitle");
  const authorNameEl = document.getElementById("authorName");
  const authorRoleEl = document.getElementById("authorRole");
  const authorAvatarEl = document.getElementById("authorAvatar");
  const updatedDateEl = document.getElementById("updatedDate");
  const introTextEl = document.getElementById("articleIntroText");

  document.title = `${currentArticle.heroTitle} | Women Hairstyles`;

  if (titleEl) titleEl.textContent = currentArticle.heroTitle;
  if (authorNameEl) authorNameEl.textContent = currentArticle.authorName;
  if (authorRoleEl) authorRoleEl.textContent = currentArticle.authorRole;
  if (authorAvatarEl) authorAvatarEl.src = currentArticle.authorAvatar;
  if (updatedDateEl) updatedDateEl.innerHTML = `<i class="far fa-clock"></i> PHOTOS UPDATED ON ${currentArticle.updatedDate.toUpperCase()}`;
  
  if (introTextEl) {
    if (currentArticle.introParagraphs && Array.isArray(currentArticle.introParagraphs)) {
      introTextEl.innerHTML = currentArticle.introParagraphs.map((p, idx) => `<p class="article-intro-p ${idx === 0 ? "intro-lead-p" : ""}">${p}</p>`).join("");
    } else {
      introTextEl.innerHTML = `<p class="article-intro-p">${currentArticle.introText}</p>`;
    }
  }

  // Render Dynamic Collapsible Vertical Jump-to TOC Links with Full Headers
  const jumpTocLinksEl = document.getElementById("jumpTocLinks");
  if (jumpTocLinksEl && currentArticle.photos) {
    jumpTocLinksEl.innerHTML = currentArticle.photos.map((p, idx) => `
      <a href="#galleryContainer" class="jump-toc-item" onclick="goToPhoto(${idx})">
        <span class="toc-item-title">${p.numberTitle}</span>
      </a>
    `).join("");
  }

  renderActiveGalleryPhoto();
}

function preloadArticleImages() {
  if (currentArticle && currentArticle.photos && Array.isArray(currentArticle.photos)) {
    currentArticle.photos.forEach(p => {
      const src = p.image || p.imageUrl;
      if (src) {
        const img = new Image();
        img.src = src;
      }
    });
  }
}

function renderActiveGalleryPhoto() {
  const photo = currentArticle.photos[currentPhotoIndex];
  if (!photo) return;

  preloadArticleImages();

  // Counter Indicator
  const counterEl = document.getElementById("galleryCounter");
  if (counterEl) {
    counterEl.textContent = `${currentPhotoIndex + 1} OF ${currentArticle.photos.length} PHOTOS`;
  }

  // Photo with instant cache swap & smooth transition
  const photoEl = document.getElementById("galleryPhoto");
  if (photoEl) {
    const newSrc = photo.image || photo.imageUrl;
    if (newSrc && !photoEl.src.endsWith(newSrc)) {
      photoEl.style.opacity = "0.5";
      setTimeout(() => {
        photoEl.src = newSrc;
        photoEl.style.opacity = "1";
      }, 50);
    } else {
      photoEl.style.opacity = "1";
    }
  }

  // Content Below Slider
  const numberTitleEl = document.getElementById("itemNumberTitle");
  const descriptionEl = document.getElementById("itemDescription");
  const benefitsEl = document.getElementById("itemBenefits");
  const downsidesEl = document.getElementById("itemDownsides");
  const techniqueEl = document.getElementById("itemTechnique");
  const faceShapeEl = document.getElementById("itemFaceShape");
  const densityEl = document.getElementById("itemDensity");

  if (numberTitleEl) numberTitleEl.textContent = photo.numberTitle;
  
  if (descriptionEl) {
    if (photo.paragraphs && Array.isArray(photo.paragraphs)) {
      descriptionEl.innerHTML = photo.paragraphs.map(p => `<p class="item-desc-para">${p}</p>`).join("");
    } else if (photo.description && photo.description.includes("\n\n")) {
      descriptionEl.innerHTML = photo.description.split("\n\n").map(p => `<p class="item-desc-para">${p}</p>`).join("");
    } else {
      descriptionEl.innerHTML = `<p class="item-desc-para">${photo.description}</p>`;
    }
  }

  if (benefitsEl) benefitsEl.textContent = photo.benefits;
  if (downsidesEl) downsidesEl.textContent = photo.downsides;
  if (techniqueEl) techniqueEl.textContent = photo.technique;
  if (faceShapeEl) faceShapeEl.textContent = photo.faceShape;
  if (densityEl) densityEl.textContent = photo.density;
}

// Touch Swipe Gesture for Mobile Slider
function initTouchSwipe() {
  const frame = document.querySelector(".gallery-photo-frame");
  if (!frame) return;

  let startX = 0;
  frame.addEventListener("touchstart", (e) => {
    startX = e.touches[0].clientX;
  });

  frame.addEventListener("touchend", (e) => {
    const endX = e.changedTouches[0].clientX;
    const diffX = startX - endX;

    if (diffX > 50) {
      nextPhoto(); // Swipe left -> Next photo
    } else if (diffX < -50) {
      prevPhoto(); // Swipe right -> Prev photo
    }
  });
}

// Arrow Slider Controls
function nextPhoto() {
  if (currentPhotoIndex < currentArticle.photos.length - 1) {
    currentPhotoIndex++;
  } else {
    currentPhotoIndex = 0;
  }
  renderActiveGalleryPhoto();
}

function prevPhoto() {
  if (currentPhotoIndex > 0) {
    currentPhotoIndex--;
  } else {
    currentPhotoIndex = currentArticle.photos.length - 1;
  }
  renderActiveGalleryPhoto();
}

function goToPhoto(index) {
  if (currentArticle && currentArticle.photos && index >= 0 && index < currentArticle.photos.length) {
    currentPhotoIndex = index;
    renderActiveGalleryPhoto();
    const container = document.getElementById("galleryContainer");
    if (container) {
      container.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }
}

function updateReadingProgressBar() {
  const progressBar = document.getElementById("readingProgressBar");
  if (!progressBar) return;
  const winScroll = document.documentElement.scrollTop || document.body.scrollTop;
  const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
  const scrolled = (winScroll / height) * 100;
  progressBar.style.width = scrolled + "%";
}

// Pinterest Share URL Handler
function pinToPinterest(event) {
  if (event) event.stopPropagation();
  const photo = currentArticle.photos[currentPhotoIndex];
  if (!photo) return;

  pinSinglePostToPinterest(event, photo.numberTitle, photo.image, photo.description);
}

function pinSinglePostToPinterest(event, title, img, desc = "") {
  if (event) event.stopPropagation();
  const pageUrl = encodeURIComponent(window.location.href);
  const mediaUrl = encodeURIComponent(window.location.origin + '/' + img);
  const description = encodeURIComponent(`${title} - Women Hairstyles`);

  const pinterestUrl = `https://pinterest.com/pin/create/button/?url=${pageUrl}&media=${mediaUrl}&description=${description}`;
  window.open(pinterestUrl, '_blank', 'width=750,height=600');
}

function shareLook(event) {
  if (event) event.stopPropagation();
  const photo = (typeof currentArticle !== 'undefined' && currentArticle && currentArticle.photos) ? currentArticle.photos[currentPhotoIndex] : null;
  const shareTitle = photo ? `${photo.numberTitle} | Women Hairstyles` : (document.title || "Women Hairstyles");
  const shareUrl = window.location.href;

  if (navigator.share) {
    navigator.share({
      title: shareTitle,
      text: `Check out this hair idea: ${shareTitle}`,
      url: shareUrl
    }).catch((err) => {
      if (err.name !== 'AbortError') {
        copyToClipboardFallback(shareUrl);
      }
    });
  } else {
    copyToClipboardFallback(shareUrl);
  }
}

function copyToClipboardFallback(text) {
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(text).then(() => {
      showToastNotification("Link copied to clipboard!");
    }).catch(() => {
      legacyCopyText(text);
    });
  } else {
    legacyCopyText(text);
  }
}

function legacyCopyText(text) {
  const textArea = document.createElement("textarea");
  textArea.value = text;
  textArea.style.position = "fixed";
  textArea.style.left = "-999999px";
  document.body.appendChild(textArea);
  textArea.focus();
  textArea.select();
  try {
    document.execCommand('copy');
    showToastNotification("Link copied to clipboard!");
  } catch (err) {
    alert("Share URL: " + text);
  }
  document.body.removeChild(textArea);
}

function showToastNotification(message) {
  let toast = document.getElementById("globalToastNotice");
  if (!toast) {
    toast = document.createElement("div");
    toast.id = "globalToastNotice";
    toast.style.position = "fixed";
    toast.style.bottom = "24px";
    toast.style.left = "50%";
    toast.style.transform = "translateX(-50%) translateY(100px)";
    toast.style.backgroundColor = "#111111";
    toast.style.color = "#FFFFFF";
    toast.style.padding = "0.75rem 1.5rem";
    toast.style.borderRadius = "30px";
    toast.style.fontSize = "0.9rem";
    toast.style.fontWeight = "600";
    toast.style.boxShadow = "0 8px 24px rgba(0, 0, 0, 0.2)";
    toast.style.zIndex = "10000";
    toast.style.transition = "transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.3s ease";
    toast.style.opacity = "0";
    toast.style.pointerEvents = "none";
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.style.opacity = "1";
  toast.style.transform = "translateX(-50%) translateY(0)";

  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateX(-50%) translateY(100px)";
  }, 2500);
}

function renderRelatedArticlesFeed() {
  const feedList = document.getElementById("relatedFeedList");
  if (!feedList) return;

  const currentId = currentArticle ? currentArticle.id : '';
  const currentCat = currentArticle ? currentArticle.category : '';

  let candidatePosts = BLOG_POSTS_DATABASE.filter(p => p.id !== currentId);

  // Sort candidates so articles in the same category are prioritized
  candidatePosts.sort((a, b) => {
    const aSame = (a.category === currentCat) ? -1 : 1;
    const bSame = (b.category === currentCat) ? -1 : 1;
    return aSame - bSame;
  });

  // Limit to maximum 6 recommended articles
  const recommended = candidatePosts.slice(0, 6);

  feedList.innerHTML = recommended.map(post => `
    <div class="related-feed-item" onclick="openBlogArticle('${post.id}')">
      <img src="${post.thumbnail}" alt="${post.heroTitle}" class="feed-thumb-img">
      <div>
        <span class="blog-tag-badge" style="font-size: 0.68rem;">${post.tag}</span>
        <h4 class="feed-item-title">${post.heroTitle}</h4>
      </div>
    </div>
  `).join("");
}

/* ==========================================================================
   GLOBAL INTERACTIVE SEARCH MODAL HANDLER
   ========================================================================== */
function initGlobalSearch() {
  const searchBtn = document.getElementById("headerSearchBtn");
  const modal = document.getElementById("globalSearchModal");
  const closeBtn = document.getElementById("closeSearchModal");
  const input = document.getElementById("globalSearchInput");

  if (!modal || !input) return;

  function openSearch() {
    modal.classList.add("active");
    input.focus();
    renderSearchModalResults("");
  }

  function closeSearch() {
    modal.classList.remove("active");
    input.value = "";
  }

  if (searchBtn) {
    searchBtn.addEventListener("click", openSearch);
  }

  if (closeBtn) {
    closeBtn.addEventListener("click", closeSearch);
  }

  modal.addEventListener("click", (e) => {
    if (e.target === modal) closeSearch();
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && modal.classList.contains("active")) {
      closeSearch();
    }
  });

  input.addEventListener("input", (e) => {
    renderSearchModalResults(e.target.value.toLowerCase().trim());
  });
}

function renderSearchModalResults(query) {
  const resultsContainer = document.getElementById("globalSearchResults");
  if (!resultsContainer) return;

  const matches = BLOG_POSTS_DATABASE.filter(post => {
    if (!query) return true;
    return post.heroTitle.toLowerCase().includes(query) ||
      post.introText.toLowerCase().includes(query) ||
      post.tag.toLowerCase().includes(query) ||
      post.category.toLowerCase().includes(query);
  });

  if (matches.length === 0) {
    resultsContainer.innerHTML = `
      <div style="text-align: center; color: #BBB; padding: 2.5rem 0;">
        <p style="font-size: 1.1rem; margin-bottom: 0.3rem;">No haircut blogs found matching "${query}"</p>
        <span style="font-size: 0.85rem; color: #777;">Try searching for 'bob', 'layers', 'balayage', or 'curly'</span>
      </div>
    `;
    return;
  }

  resultsContainer.innerHTML = matches.map(post => `
    <a href="${post.id}.html" class="search-result-item">
      <img src="${post.thumbnail}" alt="${post.heroTitle}" class="search-result-thumb">
      <div class="search-result-info">
        <span style="font-size: 0.72rem; color: var(--accent-pink); font-weight: 700; text-transform: uppercase;">${post.tag}</span>
        <div class="search-result-title">${post.heroTitle}</div>
        <div class="search-result-meta">${post.readTime} • By ${post.authorName}</div>
      </div>
    </a>
  `).join("");
}

/* ==========================================================================
   BULK TEXT COPY & SELECTION PROTECTION (Preserves Form Inputs & Images)
   ========================================================================== */
function initCopyProtection() {
  // Block Select-All (Cmd+A / Ctrl+A) outside form input/textarea elements
  document.addEventListener("keydown", (e) => {
    const isCmdOrCtrl = e.metaKey || e.ctrlKey;
    if (isCmdOrCtrl && e.key.toLowerCase() === "a") {
      const activeTag = document.activeElement ? document.activeElement.tagName.toLowerCase() : "";
      if (activeTag !== "input" && activeTag !== "textarea") {
        e.preventDefault();
      }
    }
  });

  // Block bulk text copy actions outside form inputs
  document.addEventListener("copy", (e) => {
    const activeTag = document.activeElement ? document.activeElement.tagName.toLowerCase() : "";
    if (activeTag !== "input" && activeTag !== "textarea") {
      const selection = window.getSelection();
      if (selection && selection.toString().trim().length > 0) {
        e.preventDefault();
      }
    }
  });

  // Prevent selection drag start on text elements while allowing images
  document.addEventListener("selectstart", (e) => {
    const targetTag = e.target ? e.target.tagName.toLowerCase() : "";
    if (targetTag !== "input" && targetTag !== "textarea" && targetTag !== "img") {
      e.preventDefault();
    }
  });
}